class Solution { fun longestPalindrome(word1:String,word2:String):Int{val text=word1+word2;val n=text.length;val dp=Array(n){IntArray(n)};for(i in n-1 downTo 0){dp[i][i]=1;for(j in i+1 until n)dp[i][j]=if(text[i]==text[j])2+if(i+1<=j-1)dp[i+1][j-1] else 0 else maxOf(dp[i+1][j],dp[i][j-1])};var answer=0;for(i in word1.indices)for(j in word1.length until n)if(text[i]==text[j])answer=maxOf(answer,2+if(i+1<=j-1)dp[i+1][j-1] else 0);return answer} }
